const crypto = require('crypto');
const e = $json.body;
const secret = $env.AUTOMATION_SECRET;
if (!secret || secret.length < 32) throw new Error('Automation secret is not configured');
if (!e || typeof e.payload !== 'string' || e.payload.length > 65536 || typeof e.timestamp !== 'string' || !/^\d{13}$/.test(e.timestamp) || typeof e.signature !== 'string' || !/^[a-f0-9]{64}$/.test(e.signature) || Math.abs(Date.now() - Number(e.timestamp)) > 300000) throw new Error('Invalid or expired envelope');
const expected = crypto.createHmac('sha256', secret).update(`${e.timestamp}.${e.payload}`).digest();
const received = Buffer.from(e.signature, 'hex');
if (!crypto.timingSafeEqual(expected, received)) throw new Error('Invalid signature');
const data = JSON.parse(e.payload);
if (typeof data.eventId !== 'string') throw new Error('eventId required');
return [{json: {eventId: data.eventId}}];

const crypto = require('crypto');
const secret = $env.AUTOMATION_SECRET;
if (!secret || secret.length < 32) throw new Error('Automation secret is not configured');
const timestamp = String(Date.now());
const payload = JSON.stringify({eventId: $json.eventId});
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${payload}`).digest('hex');
return [{json: {payload, timestamp, signature}}];
